head.script:
scwin.vScrenID = "ULDSTF09305.xml";
scwin.clickBzProcsNo = "";
scwin.vIsurCd = "";
scwin.clickBokRow;
scwin.vOpenTyp = ""; // R=접수, H = 이력, N : 신규
scwin.vIsuCd = "";

//scwin.fr_SecuGrpId = $c.lc.getSecuGrpId("09316");
scwin.fr_SecuGrpId = "PF";
scwin.vSYMBL_INPUT_CD = $c.session.getUserInfo("market");

scwin.onpageload = function() {
    scwin.init();
};

scwin.init = function() {
    scwin.fn_get_isurcode() ; //운용사 셀렉트 박스 조회
    scwin.fn_setComponentSymbl();
};

//운용사 조회
scwin.fn_get_isurcode = async function() {
    const sbmOptions = {
        id : "sbm_trstcom",
        method: "get",
        action : "/api/listing/lstmgt/corpchrg/select-list-isurcode",
        target : "dlt_listEtfTrstComLPRes=body.listEtfTrstComLP",
        isProcessMsg : false 
    };

	const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success == true) {
        sbx_isurCd3.setNodeSet("data:dlt_listEtfTrstComLPRes","text","value"); //운용사 셀렉트 박스 
    }
}

scwin.fn_setComponentSymbl = function() {
    if (scwin.vSYMBL_INPUT_CD == '2') {
        //영문종목심볼
        grd_List.setColumnVisible("isuEngSymbl", false);
    }
};


scwin.fn_all_list_sync = async function() {
    if("" == txb_ISU_CD.getValue()){
        await $c.win.alert("종목코드를 선택바랍니다");
        txb_ISU_CD.focus();
        return;
    }

    scwin.fn_list_sync();
};


//하단그리드 조회 
scwin.fn_list_sync = async function() {
    dlt_list.removeAll();

    var req = {
        "isuCd" : txb_ISU_CD.getValue(),
        "isurCd" : sbx_isurCd3.getValue() //운용사
    }

    const sbmOptions = {
        id: "sbm_selectlist",
        action: "/api/listing/lstproc/pf/isunmchg/select-list",
        method: "get",
        target: "dlt_list=body",
        gridview: "grd_gridView2", 
        isProcessMsg: false
    };

    const rslt = await $c.sbm.executeDynamic(sbmOptions, req);
    if(rslt.responseJSON.success){
        tbx_totCnt.setValue(dlt_list.getTotalRow());
    }

};


//팝업 호출
scwin.fn_OpenDetailMng = function(row) {
    scwin.vOpenTyp = "H";
    scwin.fn_setBzProcsNo(row);

    scwin.fn_OpenPopup();
};


//상세팝업 호출
scwin.fn_OpenPopup = async function() {
    let url = "//ui/lst/lstproc/ULDSTF05317.xml";
    let popTitle = "종목명변경 관리";

    const opts = {
        id: "ULDSTF05317",
        popupName: popTitle,
        width: 1230,
        height: 500,
        frameModal: "top",
    };

    //api 나오면 추후 확인 필요 
    let popupData = {
        "clickBzProcsNo" : scwin.clickBzProcsNo,
        "vIsurCd" : scwin.vIsurCd,
        "vOpenTyp" : scwin.vOpenTyp, 
        "vSecuGrpId" : scwin.fr_SecuGrpId,
        "vIsuCd" : scwin.vIsuCd, 
        "pageId" : "STF09316",
        "chgListMktactAdmNo" : scwin.chgListMktactAdmNo
    };

    const res = await $c.win.openPopup(url, opts, {"pData" : popupData});
    if(res){
        //팝업리턴

    }
};

//하단 그리드에서 팝업 호출시 변수 설정
scwin.fn_setBzProcsNo = function(row) {
    scwin.clickBzProcsNo = dlt_list.getCellData(row, "bzProcsNo");
    scwin.vIsurCd = dlt_list.getCellData(row, "isurCd");
    scwin.chgListMktactAdmNo = dlt_list.getCellData(row, "chgListMktactAdmNo");
};

scwin.fn_getBzProcsNo = function() {
    return scwin.clickBzProcsNo;
};


//신규버튼 클릭시 
scwin.btn_New_onclick = async function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        await $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return;
    }

    scwin.vIsuCd = txb_ISU_CD.getValue();


    scwin.vOpenTyp = "N";
    scwin.clickBzProcsNo = ""; //초기화

    scwin.fn_OpenPopup();
};


//검색버튼 클릭 
scwin.btn_Search_onclick = function() {
    scwin.fn_all_list_sync();
};

//엑셀다운로드
scwin.btn_Excel_onclick = function() {
    if (dlt_list.getRowCount() > 0) {
        const today = $c.date.getServerDateTime("yyyyMMddHHmmss");
        const options = {
            fileName : "ULDSTF09316_종목명변경 내역_" + today,
            sheetName : "리스트",
        };
        $c.data.downloadGridViewExcel(grd_List, options);
    } else {
        $c.win.alert($c.data.getMessage("com_search_0027"));
    }
};

scwin.btn_Close_onclick = async function() {
    await $c.win.closePopup();
};


//종목코드 검색 
scwin.img_ISU_CD_onclick = async function() {
    const opts = {
        id: "ULDSTF92017",
        popupName: "종목 선택",
        width: 1180,
        height: 880,
        frameModal: "top",
    };

    var result = await $c.win.openPopup("/ui/lst/common/ULDSTF92017.xml", opts, {"secugrpId" : scwin.fr_SecuGrpId});

    if(!$c.util.isEmpty(result)){
        txb_ISU_CD.setValue(result.isuCd);//종목코드
        txb_ISU_NM.setValue(result.isuKorNm);//종목명 
        scwin.vIsurCd = result.isurCd;//발행기관코드 설정 
        scwin.vIsuCd = result.isuCd;//종목코드

        //하단 그리드만 재조회가 맞는지 확인필요핟스 
        scwin.fn_list_sync();
    }
};

scwin.grd_Bok_Recv_OnDblClick = function(row, colid) {
    scwin.fn_OpenDetailBokRecv(row);
};


//하단 그리드 dbClick
scwin.grd_List_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    scwin.fn_OpenDetailMng(rowIndex);
};


//엑셀업로드
scwin.btn_excelUpload_onclick = async function (e) {
	// var res = await $c.win.confirm("엑셀자료를 업로드 하시면 그리드의 내용이 엑셀 데이터로 변경됩니다.");
    // if (res) {
    //     $c.data.uploadGridViewExcel(grd_gridView2);
    // }

    //09.29 수정
    scwin.fn_openUpload();
};

/**
 * 엑셀 일괄업로드 화면 호출
 */
scwin.fn_openUpload = async function() {

    const url = "/ui/lst/lstproc/ULDSTF05360.xml";
    const popTitle = "종목변경 엑셀일괄업로드";

    const opts = {
        id: "ULDSTF05360",
        popupName: popTitle,
        width: 1300,
        height: 750,
		type: "pageFramePopup",

    };

    await $c.win.openPopup(url, opts, {'pageId ' : 'ULDSTF09316', 'vIsurCd' : scwin.vIsurCd });
};

//엑셀업로드 샘플 다운로드
scwin.btn_FORM_U1_onclick = async function (e) {
	let url = "/api/listing/lstproc/pf/isunmchg/template-download";
    $c.data.downFile(url, "etf_isu_nm_change_sample.xlsx");
};

//엑셀다운로드
scwin.btn_Excel_3_onclick = function (e) {
	if (dlt_list.getRowCount() > 0) {
        const today = $c.date.getServerDateTime("yyyyMMddHHmmss");
        const options = {
            fileName : "ULDSTF09316_종목변경_" + today,
            sheetName : "리스트",
        };

        $c.data.downloadGridViewExcel(grd_gridView2, options);
    } else {
        $c.win.alert($c.data.getMessage("com_search_0027"));
    }
};
